import React, { useState, useEffect, useRef } from 'react';
import { Container, Button, Input, InputGroup, InputGroupText } from 'reactstrap';
import SockJS from 'sockjs-client';
import { Client } from '@stomp/stompjs';

const ChatRoom = ({ chat_id, other_user_id, login_user_id, goBack }) => {
    const [message, setMessage] = useState('');
    const [messages, setMessages] = useState([]);
    const [amount, setAmount] = useState(''); // 송금 금액
    const stompClient = useRef(null);
    const messagesEndRef = useRef(null);

    useEffect(() => {
        fetchMessages(chat_id);
        connectWebSocket();

        return () => {
            if (stompClient.current) {
                stompClient.current.deactivate();
            }
        };
    }, [chat_id]);

    useEffect(() => {
        scrollToBottom();
    }, [messages]);

    const fetchMessages = (header_id) => {
        fetch(`http://localhost:8080/api/messages/byHeaderId/${header_id}`)
            .then((response) => response.json())
            .then((data) => {
                if (Array.isArray(data)) {
                    setMessages(data);
                } else {
                    setMessages([]);
                }
            })
            .catch((error) => console.error('Error:', error));
    };

    const connectWebSocket = () => {
        const socket = new SockJS('http://localhost:8080/ws');
        stompClient.current = new Client({
            webSocketFactory: () => socket,
            onConnect: () => {
                stompClient.current.subscribe(`/topic/chat/${chat_id}`, (message) => {
                    const receivedMessage = JSON.parse(message.body);
                    setMessages((prevMessages) => [...prevMessages, receivedMessage]);
                });
            },
            onStompError: (frame) => {
                console.error('Broker reported error: ' + frame.headers['message']);
                console.error('Additional details: ' + frame.body);
            },
        });

        stompClient.current.activate();
    };

    const formatDate = (date) => {
        const year = date.getFullYear();
        const month = String(date.getMonth() + 1).padStart(2, '0');
        const day = String(date.getDate()).padStart(2, '0');
        const hours = String(date.getHours()).padStart(2, '0');
        const minutes = String(date.getMinutes()).padStart(2, '0');
        const seconds = String(date.getSeconds()).padStart(2, '0');
        const milliseconds = String(date.getMilliseconds()).padStart(3, '0');
        return `${year}-${month}-${day} ${hours}:${minutes}:${seconds}.${milliseconds}`;
    };

    const handleSend = () => {
        if (message.trim() !== '') {
            const newMessage = {
                header_id: chat_id,
                from_id: login_user_id,
                to_id: other_user_id,
                content: message.trim(),
                time: formatDate(new Date()), // 현재 시간을 설정합니다.
            };
            setMessage('');

            fetch('http://localhost:8080/api/messages', {
                method: 'POST',
                headers: {
                    'Content-Type': 'application/json',
                },
                body: JSON.stringify(newMessage),
            })
                .then((response) => response.json())
                .then((data) => {
                    stompClient.current.publish({
                        destination: `/app/chat/${chat_id}`,
                        body: JSON.stringify(data),
                    });
                })
                .catch((error) => console.error('Error:', error));
        }
    };

    const handleSendMoney = () => {
        if (amount.trim() !== '' && !isNaN(amount)) {
            fetch('http://localhost:8080/api/chats/sendPoints', {
                method: 'POST',
                headers: {
                    'Content-Type': 'application/json',
                },
                body: JSON.stringify({
                    header_id: chat_id,
                    from_id: login_user_id,
                    to_id: other_user_id,
                    amount: parseFloat(amount),
                }),
            })
                .then((response) => response.json())
                .then((data) => {
                    alert('송금 성공: ' + data);
                    setAmount('');
                })
                .catch((error) => {
                    console.error('송금 실패:', error);
                    alert('송금 실패');
                });
        }
    };

    const scrollToBottom = () => {
        messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' });
    };

    return (
        <Container style={{ position: 'relative', height: '100vh', padding: '0' }}>
            <div>
                <Button style={{ fontSize: '10px', margin: '10px' }} color="secondary" onClick={goBack}>
                    ◁
                </Button>
                {chat_id}-{other_user_id}
            </div>
            <div
                style={{
                    position: 'absolute',
                    top: '6%',
                    left: '0',
                    right: '0',
                    bottom: '50%',
                    overflowY: 'scroll',
                    padding: '5px',
                }}
            >
                {messages.map((msg) => (
                    <div
                        key={msg.id}
                        style={{
                            display: 'flex',
                            justifyContent: msg.from_id === login_user_id ? 'flex-end' : 'flex-start',
                            marginBottom: '10px',
                        }}
                    >
                        <div
                            style={{
                                maxWidth: '60%',
                                padding: '10px',
                                borderRadius: '10px',
                                background: msg.from_id === login_user_id ? '#007bff' : '#f1f0f0',
                                color: msg.from_id === login_user_id ? '#fff' : '#000',
                                wordWrap: 'break-word',
                            }}
                        >
                            {msg.content}
                        </div>
                    </div>
                ))}
                <div ref={messagesEndRef} />
            </div>
            <div
                style={{
                    position: 'absolute',
                    top: '50%',
                    left: '0',
                    width: '100%',
                    padding: '10px',
                    backgroundColor: '#fff',
                    borderTop: '1px solid #ccc',
                }}
            >
                <InputGroup>
                    <Input
                        type="text"
                        value={message}
                        onChange={(e) => setMessage(e.target.value)}
                        placeholder="메시지를 입력하세요"
                    />
                    <InputGroupText>
                        <Button color="primary" onClick={handleSend}>
                            전송
                        </Button>
                    </InputGroupText>
                </InputGroup>
                <InputGroup>
                    <Input
                        type="text"
                        value={amount}
                        onChange={(e) => setAmount(e.target.value)}
                        placeholder="송금할 금액을 입력하세요"
                    />
                    <InputGroupText>
                        <Button color="primary" onClick={handleSendMoney}>
                            송금
                        </Button>
                    </InputGroupText>
                </InputGroup>
            </div>
        </Container>
    );
};

export default ChatRoom;
